#include <stdio.h>
/* ex01：连续分配——逻辑块到物理块的换算
 * 连续分配把文件放在一段连续磁盘块里，只要记 (起始块, 长度)，
 * 第 k 个逻辑块的物理块号 = 起始块 + k。缺点：文件增长困难、产生外部碎片。*/
int main(void) {
    int start = 100, len = 8, blk = 1024;   /* 起始块、块数、块大小(字节) */
    printf("文件属性: 起始块=%d 长度=%d 块 块大小=%dB\n", start, len, blk);
    printf("-----------------------------------------------\n");
    printf("%-8s %-10s %-12s %s\n", "逻辑块", "物理块", "字节偏移区间", "是否越界");
    for (int k = 0; k <= len + 1; k++) {     /* 故意多试两个，看越界判定 */
        int phys = start + k;
        int ok = (k < len);
        printf("%-8d %-10d [%d,%d)%s%s\n", k, ok ? phys : -1,
               k * blk, (k + 1) * blk, ok ? "   " : " ", ok ? "合法" : "越界(EBADF/EIO)");
    }
    printf("\n结论: 连续分配寻址是 O(1)，代价是「必须一开始就留够空间」。\n");
    printf("      真实文件系统只在 /boot、数据库表空间这类「写入即定长」的场景用它。\n");
    return 0;
}
